legend_raw:
rvx-legend{display:flex;flex-wrap:wrap;gap:11px;margin-top:6px;font-size:11px;color:var(--muted);padding:0 4px 8px}
.rvx-legend span{display:inline-flex;align-items:center;gap:5px} .rvx-legend i{width:9px;height:9px;border-radius:50%;display:inline-block}
.rvx-rtip{position:absolute;pointer-events:none;z-index:20;min-width:170px;padding:10px 12px;border-radius:11px;background:var(--glass-bg);border:1px solid var(--glass-brd);box-shadow:var(--glass-shadow);backdrop-filter:var(--glass-blur);font-size:12px;opacity:0;transform:translateY(4px);transition:opacity .12s,transform .12s}
.rvx-rtip.on{opacity:1;transform:none}
.rvx-rtip .rt-nm{font-weight:750;font-size:13px} .rvx-rtip .rt-cat{font-size:10.5px;color:var(--muted);margin-bottom:6px}
.rvx-rtip .rt-row{display:flex;justify-content:space-between;gap:14px;margin:2px 0} .rvx-rtip .rt-row span:last-child{font-family:var(--rvx-num);font-weight:600}
.rvx-rtip .rt-stance{margin-top:7px;font-weight:700;font-size:11.5px}
/* linked board */
.rvx-board-card{padding:14px 16px}
.rvx-filters{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px}
.rvx-fbtn{font:inherit;font-size:12px;padding:5px 11px;border-radius:9px;cursor:pointer;color:var(--muted);background:var(--gbtn-bg);border:1px solid var(--gbtn-brd);box-shadow:inset 0 1px 0 var(--gbtn-sheen);transition:.15s}
.rvx-fbtn:hover{background:var(--gbtn-bg-hover);color:var(--text)}
.rvx-fbtn.on{color:var(--text);border-color:var(--gbtn-brd-hover);background:color-mix(in srgb,var(--info) 16%,var(--gbtn-bg))}
.rvx-fbtn .fc{font-family:var(--rvx-num);opacity:.7;margin-left:4px}
.rvx-brow{display:grid;grid-template-columns:22px minmax(0,1.6fr) 54px 48px 60px 50px 32px;gap:9px;align-items:center;padding:9px 6px;border-top:1px solid var(--rvx-hair);text-decoration:none;color:var(--text);border-radius:8px;animation:rvxRowPop .4s ease both}
@keyframes rvxRowPop{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}
.rvx-brow:hover{background:color-mix(in srgb,var(--panel2) 50%,transparent)}
.rvx-brow .rk{font-family:var(--rvx-num);font-size:11px;color:var(--muted);text-align:right}
.rvx-brow .bnm{font-weight:600;font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rvx-brow .bnm .cat{font-size:10px;color:var(--muted);font-weight:400}
.rvx-scorebar{height:7px;border-radius:4px;background:color-mix(in srgb,var(--text) 8%,transparent);overflow:hidden;position:relative}
.rvx-scorebar i{position:absolute;inset:0 auto 0 0;border-radius:4px}
.rvx-stag{font-size:10px;font-weight:700;padding:2px 6px;border-radius:6px;text-align:center;white-space:nowrap;
  background:color-mix(in srgb,currentColor 15%,transparent)}
.rvx-brow .mv{font-family:var(--rvx-num);font-size:12px;font-weight:600;text-align:right}
.rvx-brow .spark{height:24px} .rvx-vel{font-family:var(--rvx-num);font-size:11px;text-align:right;font-weight:600}
.rvx-qdot{width:9px;height:9px;border-radius:50%;display:inline-block;margin-right:5px;vertical-align:middle;flex:none}

/* ── INTERNALS ── */
.rvx-internals{display:grid;grid-template-columns:1.2fr repeat(4,minmax(0,1fr));gap:13px}
.rvx-gcard{padding:14px;border-radius:13px;border:1px solid var(--rvx-hair);background:color-mix(in srgb,var(--panel) 68%,transparent);text-align:center}
.rvx-gcard .gl{font-size:11px;color:var(--muted);letter-spacing:.03em}
.rvx-gcard .gv{font-family:var(--rvx-num);font-size:22px;font-weight:700;margin:5px 0 2px}
.rvx-gcard .gm{font-size:10.5px;color:var(--muted)}
.rvx-gcard.verdict{text-align:left;display:flex;flex-direction:column;justify-content:center}
.rvx-gcard.verdict .gbig{font-size:19px;font-weight:750;color:var(--ink-warn, var(--warn))}
.rvx-minibar{height:6px;border-radius:3px;background:color-mix(in srgb,var(--text) 8%,transparent);margin-top:8px;overflow:hidden;position:relative}
.rvx-minibar i{position:absolute;inset:0 auto 0 0;border-radius:3px}

@media (prefers-reduced-motion:reduce){
  .rvx-aurora b,.rvx-reveal,.rvx-brow,.rvx-hoarrow path,.rvx-rmap .lead-ring{animation:none!important}
  .rvx-reveal{opacity:1;transform:none} .rvx-hoarrow path.ln{stroke-dashoffset:0} .rvx-hoarrow path.hd{opacity:1}
}
@media (max-width:900px){
  .rvx-hgrid{grid-template-columns:1fr} .rvx-vword{font-size:30px}
  .rvx-lanes{grid-template-columns:1fr 1fr} .rvx-map-wrap{grid-template-columns:1fr}
  .rvx-internals{grid-template-columns:1fr 1fr}
}
@media (max-width:560px){ .rvx-lanes{grid-template-columns:1fr} }
.mr-sec .mr-limit{margin:4px 0 10px;color:var(--muted);font-size:var(--fs-sm)}
.mr-status{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 10px} .mr-status:empty{display:none}
.mr-chip{display:inline-flex;align-items:center;min-height:24px;padding:2px 10px;border-radius:var(--r-ctl,8px);font-size:var(--fs-label);border:1px solid var(--line);color:var(--muted)}
.mr-chip-partial{background:var(--ff-tint-info-8);color:var(--ink-info);border-color:transparent}
.mr-chip-stale{background:var(--ff-tint-warn-6);color:var(--ink-warn);border-color:transparent}
.mr-grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:var(--sp-4,16px);align-items:start}
.mr-listbox,.mr-detail{padding:var(--sp-4,16px)}
.mr-cov{font-size:var(--fs-sm);color:var(--muted);margin:0 0 10px;line-height:1.5} .mr-cov b{color:var(--text);font-weight:600}
.mr-head,.mr-row{display:grid;grid-template-columns:minmax(0,1fr) 64px 64px;gap:8px;align-items:center}
.mr-head{font-size:var(--fs-micro);text-transform:uppercase;letter-spacing:.06em;color:var(--muted);padding:0 10px 6px;border-bottom:1px solid var(--line)}
.mr-head span+span,.mr-c{text-align:right}
.mr-list{list-style:none;margin:0;padding:0} .mr-list[hidden]{display:none}
.mr-unmeasured{margin-top:8px;padding-top:8px;border-top:1px dashed var(--line)}
.mr-row{width:100%;min-height:40px;padding:6px 10px;background:none;border:0;border-radius:var(--r-ctl,8px);color:var(--text);font:inherit;font-size:var(--fs-md);text-align:left;cursor:pointer}
.mr-row-na{grid-template-columns:minmax(0,1fr) auto}
.mr-row:hover{background:var(--panel2)}
.mr-row:focus-visible,.mr-segbtn:focus-visible,.mr-link:focus-visible{outline:2px solid var(--ink-info);outline-offset:2px}
.mr-row[aria-pressed="true"]{background:var(--panel2);box-shadow:none}
.mr-name{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mr-c{font-family:var(--font-mono);font-size:var(--fs-sm)}
.mr-up{color:var(--ink-up)} .mr-down{color:var(--ink-down)} .mr-flat,.mr-na{color:var(--muted)}
.mr-why{font-size:var(--fs-sm);color:var(--muted);text-align:right}
.mr-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.mr-foot{margin:10px 0 0;font-size:var(--fs-label);color:var(--muted)}
.mr-detail{background:var(--panel2);border:1px solid var(--line);box-shadow:none;backdrop-filter:none}
.mr-hint{margin:0;color:var(--muted);font-size:var(--fs-sm)}
.mr-dh{margin:0 0 10px;font-size:var(--fs-md);font-weight:600;color:var(--text)}
.mr-tk{margin-left:6px;font-family:var(--font-mono);font-size:var(--fs-label);color:var(--muted)}
.mr-facts{display:grid;grid-template-columns:1fr 1fr;gap:8px 16px;margin:0 0 14px} .mr-facts div{min-width:0}
.mr-facts dt{font-size:var(--fs-label);color:var(--muted)} .mr-facts dd{margin:2px 0 0;font-size:var(--fs-md);color:var(--text)}
.mr-seg{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0 0 10px} .mr-seg-l{font-size:var(--fs-label);color:var(--muted);margin-right:4px}
.mr-segbtn{min-height:40px;padding:6px 12px;border:1px solid var(--line);border-radius:var(--r-ctl,8px);background:none;color:var(--muted);font:inherit;font-size:var(--fs-sm);cursor:pointer}
.mr-segbtn[aria-pressed="true"]{color:var(--text);border-color:var(--ink-info);background:var(--ff-tint-info-8)}
.mr-spark{display:block;width:100%;height:64px}
.mr-spark-line{fill:none;stroke:var(--ink-info);stroke-width:1.5} .mr-spark-zero{stroke:var(--line);stroke-dasharray:3 3}
.mr-hist-cap{margin:6px 0 0;font-size:var(--fs-label);color:var(--muted);line-height:1.5}
.mr-skel-line{height:14px;width:60%} .mr-skel-row{height:32px;margin:6px 0} .mr-skel-spark{height:64px}
.mr-gen{padding:10px 12px;border-radius:var(--r-ctl,8px);background:var(--ff-tint-warn-6);color:var(--text);font-size:var(--fs-sm)} .mr-gen b{color:var(--ink-warn)}
.mr-invalid{padding:12px 14px;border:1px dashed var(--line);border-radius:var(--r-card,12px);color:var(--muted);font-size:var(--fs-sm)}
.mr-obs{margin:0 0 8px;font-size:var(--fs-sm);color:var(--text)}
.mr-link{display:inline-flex;align-items:center;min-height:40px;color:var(--ink-link);font-size:var(--fs-sm);text-decoration:none} .mr-link:hover{text-decoration:underline}
.mr-early{margin-top:var(--sp-4,16px);padding:12px 14px;border:1px solid var(--line);border-radius:var(--r-card,12px);background:var(--panel2)}
.mr-early-lab{font-size:var(--fs-label);color:var(--muted);margin:0 0 4px} .mr-early-clause{margin:0 0 4px;font-size:var(--fs-md);color:var(--text)} .mr-early-cov{margin:0;font-size:var(--fs-sm);color:var(--muted)}
.mr-noforecast{margin:8px 0 0;font-size:var(--fs-label);color:var(--muted)}
/* LIGHT TREATMENT — research workspace: white material, hairline, shadow instead of glow */
html[data-theme="light"] .mr-row:hover{background:var(--ff-tint-muted-8)}
html[data-theme="light"] .mr-row[aria-pressed="true"]{background:var(--ff-tint-info-8)}
html[data-theme="light"] .mr-detail,html[data-theme="light"] .mr-early{background:var(--panel);box-shadow:var(--card-shadow)}
html[data-theme="light"] .mr-spark-line{stroke-width:1.75}
@media (max-width:760px){ .mr-grid{grid-template-columns:minmax(0,1fr)} .mr-row,.mr-segbtn,.mr-link{min-height:44px} .mr-head,.mr-row{grid-template-columns:minmax(0,1fr) 58px 58px} .mr-name{white-space:normal} .mr-row-na{grid-template-columns:minmax(0,1fr);gap:2px} .mr-row-na .mr-why{text-align:left} }


  /* ══════════════════════════════════════════════════════════════════════════
     CONFLUENCE VIEW (6th rail view) — the US subsector-confluence board, brought
     from the standalone subsectors page and mounted here by the router
     (subsectors.js writes group cards + tables into #sc-app).

     The donor page's page-local  was authored for a page it owned outright:
     it carries global resets (*, body, a) and scopes its own rules with
     `body.page-subsectors`, neither of which survives the move. This page defines
     .card / .pos / .neg differently and hosts five other rail views that must not
     inherit any of it. So every rule below is re-anchored to #si-confluence — the
     id lifts specificity above this page's bare-class rules INSIDE the view and
     constrains it to nothing outside. The donor's resets are dropped (this page
     owns them); its light-mode and zh overrides are carried through re-anchored,
     not lost. Nothing is changed beyond the scope prefix. All five sc-* keyframes
     pass through unrenamed — none collides here.
     ══════════════════════════════════════════════════════════════════════════ */
  #si-confluence { --sc-num:var(--font-mono); }
  #si-confluence .sc-num, #si-confluence .num { font-family:var(--sc-num,var(--font-mono)); font-variant-numeric:tabular-nums; }
  #si-confluence .wrap { padding:14px; }
@media (min-width:1100px) {
  #si-confluence .wrap { padding:16px max(28px,calc((100vw - 1580px)/2)); }
}
  #si-confluence .sc-top { margin:6px 2px 4px; }
  #si-confluence .sc-kicker { display:flex; align-items:center; gap:9px; }
  #si-confluence .sc-kicker h2 { font-size:23px; margin:0; font-weight:800; letter-spacing:-.02em; display:flex; align-items:center; gap:9px; }
  #si-confluence .ic-svg { width:1em; height:1em; display:inline-block; flex:none; fill:none; stroke:currentColor; stroke-width:1.8; stroke-linecap:round; stroke-linejoin:round; vertical-align:-.135em; }
  #si-confluence .sc-kicker .sc-h1-ic { width:22px; height:22px; color:var(--ink-info, var(--info)); stroke-width:1.7; filter:drop-shadow(0 0 12px color-mix(in srgb,var(--info) 55%,transparent)); }
  #si-confluence .sc-h2-ic { width:17px; height:17px; color:var(--muted); stroke-width:1.7; }
  #si-confluence .sc-s1 .sc-h2-ic, #si-confluence .sc-s2 .sc-h2-ic { color:var(--ink-info, var(--info)); }
  #si-confluence .sc-h3-ic { width:15px; height:15px; stroke-width:1.7; }
  #si-confluence .sc-h3-ic.ic-run { color:var(--ink-up, var(--up)); }
  #si-confluence .sc-h3-ic.ic-coil { color:var(--ink-info, var(--info)); }
  #si-confluence .sc-search .sc-find-ic { width:14px; height:14px; color:var(--muted); }
  #si-confluence .lc-filtered .lc-veto-ic { width:12px; height:12px; margin-right:2px; }
  #si-confluence .nav-context-link .ic-svg { width:15px; height:15px; margin-right:1px; }
  #si-confluence .sc-asof { color:var(--muted); font-size:12px; margin-left:auto; font-family:var(--sc-num); }
  #si-confluence .sc-lede { color:var(--muted); font-size:12.5px; margin:5px 2px 0; max-width:82ch; line-height:1.5; }
  #si-confluence .sc-lede b { color:var(--text); font-weight:650; }
  #si-confluence .sc-tabs { display:flex; flex-wrap:wrap; gap:5px; margin:15px 2px 0; }
  #si-confluence .sc-tab { display:flex; align-items:center; gap:7px; padding:8px 15px; cursor:pointer; font-weight:650; font-size:13px; color:var(--muted); background:var(--gbtn-bg); border:1px solid var(--gbtn-brd); border-radius:11px; transition:color .16s, border-color .16s, background .16s, transform .12s; }
  #si-confluence .sc-tab:hover { color:var(--text); border-color:var(--gbtn-brd-hover); transform:translateY(-1px); }
  #si-confluence .sc-tab.on { color:var(--text); background:color-mix(in srgb,var(--info) 15%,var(--panel)); border-color:color-mix(in srgb,var(--info) 50%,transparent); box-shadow:0 0 0 1px color-mix(in srgb,var(--info) 24%,transparent), 0 6px 18px -10px color-mix(in srgb,var(--info) 60%,transparent); }
  #si-confluence .sc-tab .n { font-size:11px; font-weight:700; color:var(--muted); font-family:var(--sc-num); background:color-mix(in srgb,var(--text) 8%,transparent); padding:1px 6px; border-radius:6px; min-width:20px; text-align:center; }
  #si-confluence .sc-tab.on .n { color:var(--ink-info, var(--info)); background:color-mix(in srgb,var(--info) 16%,transparent); }
  #si-confluence .star-badge { display:inline-flex; align-items:center; line-height:0; }
  #si-confluence .star-badge .ic-svg { width:13px; height:13px; stroke-width:1.55; stroke:#e8b93c; fill:color-mix(in srgb,#e8b93c 20%,transparent); filter:drop-shadow(0 0 6px color-mix(in srgb,#e8b93c 45%,transparent)); }
  #si-confluence .isle { position:relative; background:var(--glass-bg); border:1px solid var(--glass-brd); border-radius:18px; box-shadow:var(--glass-shadow); backdrop-filter:var(--glass-blur); -webkit-backdrop-filter:var(--glass-blur); padding:18px 20px; }
  #si-confluence .isle::before { content:""; position:absolute; inset:0; border-radius:inherit; pointer-events:none; background:radial-gradient(120% 90% at 8% -10%, color-mix(in srgb,var(--isle-color,var(--info)) 12%,transparent), transparent 60%); }
  #si-confluence .isle > * { position:relative; }
  #si-confluence .sc-hero { --isle-color:var(--info); margin:16px 0 8px; padding:20px 22px 18px; overflow:hidden; }
  #si-confluence .sc-hero::after { content:""; position:absolute; left:-30%; top:-60%; width:60%; height:180%; z-index:0; pointer-events:none; background:radial-gradient(closest-side, color-mix(in srgb,var(--isle-color) 22%,transparent), transparent 70%); opacity:.5; filter:blur(30px); animation:sc-underglow 6s ease-in-out infinite; }
@keyframes sc-underglow { 0%,100%{opacity:.34;transform:translateX(0)} 50%{opacity:.6;transform:translateX(12px)} }
  #si-confluence .sc-eyebrow { display:flex; align-items:center; gap:10px; margin-bottom:14px; flex-wrap:wrap; }
  #si-confluence .sc-eyebrow .dot { width:8px; height:8px; border-radius:50%; background:var(--isle-color); flex-shrink:0; box-shadow:0 0 10px 2px color-mix(in srgb,var(--isle-color) 55%,transparent); animation:sc-beacon 3s ease-in-out infinite; }
@keyframes sc-beacon { 0%,100%{opacity:.55} 50%{opacity:1} }
  #si-confluence .sc-eyebrow .lbl { font-size:11px; font-weight:800; letter-spacing:.14em; text-transform:uppercase; color:var(--isle-color); }
  #si-confluence .sc-eyebrow .backdrop { margin-left:auto; display:flex; gap:6px; flex-wrap:wrap; align-items:center; }
  #si-confluence .bd-chip { display:inline-flex; align-items:center; gap:5px; font-size:11px; font-weight:650; padding:3px 9px; border-radius:999px; border:1px solid var(--line); background:color-mix(in srgb,var(--panel2) 60%,transparent); color:var(--muted); white-space:nowrap; }
  #si-confluence .bd-chip b { color:var(--text); font-weight:750; }
  #si-confluence .bd-chip .bd-ic { font-size:11px; }
  #si-confluence .bd-chip.bd-riskon { color:var(--ink-up, var(--up)); border-color:color-mix(in srgb,var(--up) 40%,transparent); }
  #si-confluence .bd-chip.bd-riskoff { color:var(--ink-down, var(--down)); border-color:color-mix(in srgb,var(--down) 40%,transparent); }
  #si-confluence .bd-chip.bd-mixed { color:var(--ink-orange, var(--orange)); border-color:color-mix(in srgb,var(--orange) 40%,transparent); }
  #si-confluence .bd-chip .num { color:inherit; }
  #si-confluence .sc-hero-grid { display:grid; grid-template-columns:auto 1fr; gap:22px; align-items:center; }
@media (max-width:720px) {
  #si-confluence .sc-hero-grid { grid-template-columns:1fr; gap:16px; }
}
  #si-confluence .sc-headline { text-align:center; padding:2px 10px 2px 2px; border-right:1px solid var(--line); }
@media (max-width:720px) {
  #si-confluence .sc-headline { border-right:none; border-bottom:1px solid var(--line); padding:0 0 12px; }
}
  #si-confluence .sc-headline .big { font-family:var(--sc-num); font-size:64px; line-height:.92; font-weight:800; letter-spacing:-.03em; color:var(--ink-up, var(--up)); filter:drop-shadow(0 0 16px color-mix(in srgb,var(--up) 42%,transparent)); }
  #si-confluence .sc-headline .big.zero { color:var(--muted); filter:none; }
  #si-confluence .sc-headline .cap { font-size:10.5px; font-weight:800; letter-spacing:.1em; text-transform:uppercase; color:var(--muted); margin-top:3px; }
  #si-confluence .sc-ribbon-wrap { min-width:0; }
  #si-confluence .sc-ribbon-label { display:flex; justify-content:space-between; align-items:baseline; margin-bottom:7px; }
  #si-confluence .sc-ribbon-label .t { font-size:11px; font-weight:800; letter-spacing:.1em; text-transform:uppercase; color:var(--muted); }
  #si-confluence .sc-ribbon-label .h { font-size:11px; color:var(--muted); font-family:var(--sc-num); }
  #si-confluence .sc-ribbon { display:flex; width:100%; height:44px; border-radius:11px; overflow:hidden; border:1px solid var(--line); background:color-mix(in srgb,var(--panel2) 50%,transparent); }
  #si-confluence .sc-seg { position:relative; min-width:2px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:1px; color:#fff; overflow:hidden; transform-origin:left; animation:sc-seg-grow .7s cubic-bezier(.22,1,.36,1) backwards; }
@keyframes sc-seg-grow { from{ transform:scaleX(0); opacity:.3 } to{ transform:scaleX(1); opacity:1 } }
  #si-confluence .sc-seg .sc-seg-n { font-family:var(--sc-num); font-size:15px; font-weight:800; line-height:1; text-shadow:0 1px 3px rgba(0,0,0,.4); }
  #si-confluence .sc-seg .sc-seg-t { font-size:8.5px; font-weight:700; letter-spacing:.04em; text-transform:uppercase; opacity:.92; white-space:nowrap; text-shadow:0 1px 2px rgba(0,0,0,.4); }
  #si-confluence .sc-seg.narrow .sc-seg-t { display:none; }
  #si-confluence .sc-seg.tiny .sc-seg-n { font-size:12px; }
  #si-confluence .sc-seg.entry { background:linear-gradient(180deg,var(--up),color-mix(in srgb,var(--up) 78%,#000)); box-shadow:inset 0 0 20px color-mix(in srgb,#fff 22%,transparent); }
  #si-confluence .sc-seg.tailwind { background:linear-gradient(180deg,color-mix(in srgb,var(--up) 62%,var(--info)),color-mix(in srgb,var(--up) 44%,var(--info))); }
